UPDATE notificaciones SET mensaje=regexp_replace(mensaje, ' cambió a RESOLVED$', ' cambió a RESUELTO');
UPDATE notificaciones SET mensaje=regexp_replace(mensaje, ' cambió a CLOSED$', ' cambió a CERRADO');
UPDATE notificaciones SET mensaje=regexp_replace(mensaje, ' cambió a CANCELLED$', ' cambió a CANCELADO');
UPDATE registro_auditoria SET detalles=CASE detalles WHEN 'NEW' THEN 'NUEVO' WHEN 'ASSIGNED' THEN 'ASIGNADO' WHEN 'IN_PROGRESS' THEN 'EN_ATENCION' WHEN 'PENDING' THEN 'PENDIENTE' WHEN 'RESOLVED' THEN 'RESUELTO' WHEN 'CLOSED' THEN 'CERRADO' WHEN 'CANCELLED' THEN 'CANCELADO' WHEN 'OPEN' THEN 'ABIERTO' WHEN 'UNDER_INVESTIGATION' THEN 'EN_INVESTIGACION' WHEN 'KNOWN_ERROR' THEN 'ERROR_CONOCIDO' WHEN 'ACTIVE' THEN 'ACTIVO' WHEN 'INACTIVE' THEN 'INACTIVO' WHEN 'ARCHIVED' THEN 'ARCHIVADO' WHEN 'MAINTENANCE' THEN 'EN_MANTENIMIENTO' WHEN 'RETIRED' THEN 'RETIRADO' WHEN 'LOW' THEN 'BAJO' WHEN 'MEDIUM' THEN 'MEDIO' WHEN 'HIGH' THEN 'ALTO' WHEN 'CRITICAL' THEN 'CRITICO' WHEN 'PUBLIC' THEN 'PUBLICO' WHEN 'INTERNAL' THEN 'INTERNO' WHEN 'ADMIN' THEN 'ADMINISTRADOR' WHEN 'USER' THEN 'USUARIO' WHEN 'SERVICE_DESK' THEN 'MESA_SERVICIO' WHEN 'TECHNICIAN' THEN 'TECNICO' WHEN 'INCIDENT_MANAGER' THEN 'GESTOR_INCIDENTES' WHEN 'PROBLEM_MANAGER' THEN 'GESTOR_PROBLEMAS' WHEN 'CREATE' THEN 'REGISTRO' WHEN 'UPDATE' THEN 'ACTUALIZACION' WHEN 'SAVE' THEN 'GUARDADO' WHEN 'ASSIGN' THEN 'ASIGNACION' WHEN 'REASSIGN' THEN 'REASIGNACION' WHEN 'STATUS' THEN 'CAMBIO_ESTADO' WHEN 'CLASSIFY' THEN 'CLASIFICACION' WHEN 'COMMENT' THEN 'COMENTARIO' WHEN 'UPDATE_PROFILE' THEN 'ACTUALIZAR_PERFIL' WHEN 'CHANGE_PASSWORD' THEN 'CAMBIAR_CONTRASENA' WHEN 'LINK_INCIDENT' THEN 'VINCULAR_INCIDENCIA' WHEN 'LINK_PROBLEM' THEN 'VINCULAR_PROBLEMA' WHEN 'UNLINK_INCIDENT' THEN 'DESVINCULAR_INCIDENCIA' WHEN 'UNLINK_PROBLEM' THEN 'DESVINCULAR_PROBLEMA' WHEN 'INCIDENT' THEN 'INCIDENCIA' WHEN 'PROBLEM' THEN 'PROBLEMA' WHEN 'CATEGORY' THEN 'CATEGORIA' WHEN 'CONFIGURATION_ITEM' THEN 'ELEMENTO_CONFIGURACION' WHEN 'SERVER' THEN 'SERVIDOR' WHEN 'SOFTWARE' THEN 'APLICACION' WHEN 'HARDWARE' THEN 'EQUIPO' WHEN 'NETWORK' THEN 'RED' WHEN 'SERVICE' THEN 'SERVICIO' WHEN 'WORKSTATION' THEN 'ESTACION_TRABAJO' WHEN 'LAPTOP' THEN 'PORTATIL' WHEN 'PRINTER' THEN 'IMPRESORA' WHEN 'PC' THEN 'COMPUTADORA' WHEN 'ROUTER' THEN 'ENRUTADOR' WHEN 'UNKNOWN' THEN 'DESCONOCIDO' ELSE detalles END WHERE accion='COMENTARIO' OR (entidad='PROBLEMA' AND accion='ACTUALIZACION');
